// <auto-generated />
import { useQuery } from '@tanstack/react-query';
import type { UseQueryOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import { ApiError } from '../errors/ApiError';
import type { User } from '../models';
import type { UserId } from '../types/BrandedIds';

const usersKeys = {
  all: ['users'] as const,
  getUser: (id: UserId) => [...usersKeys.all, 'getUser', id] as const,
};

export { usersKeys };

export function useGetUser(id: UserId, options?: Omit<UseQueryOptions<User, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: usersKeys.getUser(id),
    queryFn: async () => {
      const result = await api.users.getUser(id);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    enabled: !!id,
    ...options,
  });
}